<script setup lang="ts">
import type{DataRow,PageConfig}from'~/types/platform';const props=defineProps<{page:PageConfig;routePath:string}>();const{request}=useApi();const{showToast}=useToast();const model=reactive<DataRow>({});const id=ref('');onMounted(async()=>{const r=await request<{data:DataRow[]}>(props.routePath,{query:{limit:1}});if(r.data[0]){Object.assign(model,r.data[0]);id.value=String(r.data[0].id)}});const save=async()=>{if(id.value)await request(`${props.routePath}/${encodeURIComponent(id.value)}`,{method:'PUT',body:model});showToast('Company information saved.')};const fields=[['companyName','Company Name'],['legalName','Legal Name'],['address','Address'],['phone','Phone'],['email','Email'],['website','Website'],['npwp','NPWP'],['nib','NIB'],['bank','Bank'],['currency','Currency'],['fiscalYear','Fiscal Year']];const onSave=()=>save();onMounted(()=>window.addEventListener('sop:save',onSave));onBeforeUnmount(()=>{if(import.meta.client)window.removeEventListener('sop:save',onSave)})
</script>
<template><PageActions primary-label="Save Company" :hide-import="true" :hide-filter="true" @create="save" @export="showToast('Company configuration exported.')" @refresh="showToast('Company information refreshed.')" @more="showToast('More actions.')"/><section class="platform-card settings-form"><label v-for="field in fields" :key="field[0]" class="platform-field"><span>{{field[1]}}</span><input v-model="model[field[0]]"></label><label class="platform-field full"><span>Company Logo</span><input type="file" accept="image/*"></label></section></template>
